ALTER TABLE "cancellation_policies" DROP CONSTRAINT "policy_valid_values";--> statement-breakpoint
ALTER TABLE "cancellation_policies" ADD COLUMN "reschedule_notice_hours" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "cancellation_policies" ADD CONSTRAINT "policy_valid_values" CHECK ("cancellation_policies"."reschedule_notice_hours" between 0 and 720 and "cancellation_policies"."notice_hours" >= 0 and "cancellation_policies"."late_fee_value" >= 0 and "cancellation_policies"."no_show_fee_value" >= 0 and "cancellation_policies"."late_fee_type" in ('percentage','fixed') and "cancellation_policies"."no_show_fee_type" in ('percentage','fixed') and ("cancellation_policies"."late_fee_type" <> 'percentage' or "cancellation_policies"."late_fee_value" <= 100) and ("cancellation_policies"."no_show_fee_type" <> 'percentage' or "cancellation_policies"."no_show_fee_value" <= 100));